-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- EPHESIANS - POR Combined
-- Generated: 2026-01-22T06:37:36.005Z

-- c006-v001: Os filhos, obedecei aos pais vossos, no Senhor; isto pois é justo.
-- c006-v002: Honra o pai teu e a mãe, a–qual é mandamento primeiro, com promessa,
-- c006-v003: para–que bem a–ti seja, e sejas de–longa–vida sobre a terra.
-- c006-v004: E os pais, não provoqueis–à–ira os filhos vossos, mas criai–os a–eles na disciplina e admoestação do–Senhor.
-- c006-v005: Os servos, obedecei aos segundo a–carne senhores com temor e tremor, na singeleza do coração vosso, como ao Cristo;
-- c006-v006: não segundo servindo–aos–olhos como que–agradam–a–homens; mas como servos de–Cristo, fazendo a vontade de Deus de alma,
-- c006-v007: com boa–vontade servindo como ao Senhor, e não a–homens;
-- c006-v008: sabendo que cada–um, se algo fizer de–bom, isto receberá da–parte–do Senhor, seja servo seja livre.
-- c006-v009: E os senhores, as mesmas–coisas, fazei para–com eles, deixando a ameaça, sabendo que tanto deles quanto vosso o Senhor está nos céus, e acepção–de–pessoas não há com ele.
-- c006-v010: Do resto, fortalecei–vos no Senhor, e na a força do poder dele.
-- c006-v011: revesti–vos de–a armadura–completa de Deus, para o poderdes vós permanecer–firmes contra as ciladas do diabo;
-- c006-v012: porque não é a–nós a luta contra sangue e carne; mas contra os principados, contra as autoridades, contra os dominadores–do–mundo desta treva presente, contra as forças–espirituais da maldade nos os lugares–celestiais.
-- c006-v013: por isso, tomai a armadura–completa de Deus, para–que possais resistir no o dia o mau, e tendo–feito–tudo tendo–realizado, permanecer–firmes.
-- c006-v014: ficai–firmes pois, tendo–cingido os lombos vossos, com verdade, e tendo–revestido a couraça da justiça,
-- c006-v015: e tendo–calçado os pés com a–prontidão do evangelho da paz.
-- c006-v016: em tudo, tendo–tomado o escudo da fé, com o–qual podereis todos os dardos do maligno os inflamados, apagar.
-- c006-v017: e o capacete da salvação recebei, e a espada do Espírito, que é a–palavra de–Deus;
-- c006-v018: por–meio–de toda oração e súplica, orando em todo tempo no Espírito, e para isto–mesmo, vigiando com toda perseverança, e súplica, por todos os santos;
-- c006-v019: e por mim, para–que me seja–dada palavra no abrir da boca minha, em ousadia fazer–conhecido o mistério do evangelho,
-- c006-v020: pelo qual sou–embaixador em cadeias, para–que nele próprio fale–ousadamente, como é–necessário a–mim falar.
-- c006-v021: Para–que porém saibais também vós, as–coisas acerca–de mim, que faço, tudo fará–saber a–vós Tíquico, o amado irmão, e fiel ministro no Senhor;
-- c006-v022: o–qual enviei a vós para isto mesmo, para–que conheçais as–coisas acerca–de nós, e console os corações vossos.
-- c006-v023: Paz aos irmãos, e amor com fé, da–parte–de Deus Pai, e do–Senhor Jesus Cristo.
-- c006-v024: A graça com todos os que–amam o Senhor nosso, Jesus Cristo, em incorrupção.

